import { rawElements, type RawElement } from './inline-opaque'
import { decodeEntities } from './parse-xml-text'

/**
 * One part's generated byte ranges. Original and verbatim XML reserve their
 * content-control ids even when they follow generated content. Only controls
 * whose opening tag was generated may yield; copied bytes are never rewritten.
 * Temporary comments carry range provenance through surgical table/HF assembly
 * and are removed before any bytes leave the engine.
 */
export class ContentControlPart {
  private readonly prefix: string

  constructor(source: string | readonly string[]) {
    const sources = typeof source === 'string' ? [source] : source
    let prefix = 'seuoffice-inline-generated'
    while (sources.some((xml) => xml.includes(prefix))) prefix += '-'
    this.prefix = prefix
  }

  generated(xml: string): string {
    if (!/<w:sdt[\s/>]/.test(xml)) return xml
    return `<!--${this.prefix}:start-->${xml}<!--${this.prefix}:end-->`
  }

  finish(xml: string): string {
    const cuts: Array<[number, number]> = []
    const generated: Array<[number, number]> = []
    let depth = 0
    let from = 0
    const re = new RegExp(`<!--${this.prefix}:(start|end)-->`, 'g')
    for (let m = re.exec(xml); m; m = re.exec(xml)) {
      const end = m.index + m[0].length
      cuts.push([m.index, end])
      if (m[1] === 'start') {
        if (depth++ === 0) from = end
      } else if (--depth === 0) generated.push([from, m.index])
    }
    if (cuts.length === 0) return xml

    const controls: Array<{ el: RawElement; id: string; generated: boolean }> = []
    const todo = rawElements(xml, true).reverse()
    let at = 0
    for (let el = todo.pop(); el; el = todo.pop()) {
      while (at < generated.length && generated[at][1] <= el.start) at++
      if (el.name === 'w:sdt') {
        const props = el.children.find((c) => c.name === 'w:sdtPr')
        const idTag = props?.children.find((c) => c.name === 'w:id')
        const attr =
          idTag &&
          /\bw:val\s*=\s*(?:"([^"]*)"|'([^']*)')/.exec(xml.slice(idTag.start, idTag.openEnd))
        if (attr) {
          let id = decodeEntities(attr[1] ?? attr[2])
          if (/^[+-]?\d+$/.test(id))
            id = id
              .replace(/^\+/, '')
              .replace(/^(-?)0+(?=\d)/, '$1')
              .replace(/^-0$/, '0')
          controls.push({
            el,
            id,
            generated: at < generated.length && generated[at][0] <= el.start,
          })
        }
      }
      for (let i = el.children.length - 1; i >= 0; i--) todo.push(el.children[i])
    }
    const taken = new Set(controls.filter((c) => !c.generated).map((c) => c.id))
    for (const { el, id, generated: fresh } of controls) {
      if (!fresh) continue
      if (!taken.has(id)) {
        taken.add(id)
        continue
      }
      // Unwrap, do not delete content. Even a malformed control with readable
      // children outside sdtContent keeps those children in their old order.
      cuts.push([el.start, el.openEnd], [el.closeStart, el.end])
      for (const child of el.children) {
        if (child.name === 'w:sdtPr' || child.name === 'w:sdtEndPr')
          cuts.push([child.start, child.end])
        else if (child.name === 'w:sdtContent')
          cuts.push([child.start, child.openEnd], [child.closeStart, child.end])
      }
    }
    cuts.sort((a, b) => a[0] - b[0])
    const parts: string[] = []
    let cursor = 0
    for (const [start, end] of cuts) {
      if (start > cursor) parts.push(xml.slice(cursor, start))
      cursor = Math.max(cursor, end)
    }
    parts.push(xml.slice(cursor))
    return parts.join('')
  }
}
